import sqlite3


class ConnectionPool:
    def __init__(self, size):
        self._pool = [sqlite3.connect(":memory:") for _ in range(size)]
        for conn in self._pool:
            conn.execute("CREATE TABLE items (id INTEGER PRIMARY KEY, name TEXT)")

    def acquire(self):
        if not self._pool:
            raise RuntimeError("pool exhausted")
        return self._pool.pop()

    def release(self, conn):
        self._pool.append(conn)


def run_query(pool, name):
    conn = pool.acquire()
    try:
        conn.execute("INSERT INTO items (name) VALUES (?)", (name,))
        conn.commit()
        count = conn.execute("SELECT COUNT(*) FROM items").fetchone()[0]
        return count
    finally:
        pool.release(conn)


pool = ConnectionPool(size=2)
print("available before:", len(pool._pool))
print("count after insert 1:", run_query(pool, "a"))
print("available after one use:", len(pool._pool))
print("count after insert 2:", run_query(pool, "b"))
print("count after insert 3:", run_query(pool, "c"))
